import {createNotificationInbox} from './notifications.js';
import {createDiscovery} from './discovery.js';
import {createSafety} from './safety.js';
import {createAdminPanel} from './admin.js';
import {createEventsController} from './events.js';
import {SUPABASE_URL,SUPABASE_KEY} from './config.js';
import {createTogetherClient} from './client.js';
import {enableInstall} from './pwa.js';
const $=id=>document.getElementById(id);
let events,editingEvent=null,inbox,discovery,safety,admin;
let api,mode='login',user=null,profile=null,generation=0;
function notify(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error);$('notice').hidden=false;}
function message(e){const map={invalid_credentials:'Nieprawidłowy e-mail lub hasło.',email_not_confirmed:'Najpierw potwierdź adres e-mail w wiadomości od Supabase.',over_email_send_rate_limit:'Osiągnięto limit wiadomości. Odczekaj kilka minut.',over_request_rate_limit:'Zbyt wiele prób. Spróbuj ponownie później.',user_already_exists:'Nie można zarejestrować tego adresu. Spróbuj się zalogować.',signup_disabled:'Rejestracja jest wyłączona w Supabase.',weak_password:'Hasło nie spełnia wymagań Supabase.',session_expired:'Sesja wygasła. Zaloguj się ponownie.'};if(e.code==='42501')return 'Baza odrzuciła operację ze względu na uprawnienia.';return map[e.code]||e.message||'Coś poszło nie tak. Spróbuj ponownie.';}
async function busy(element,action){const buttons=[...element.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await action();}catch(e){notify(message(e),true);if(e.status===401){generation++;showAuth();}}finally{buttons.forEach(b=>b.disabled=false);}}
function showAuth(){inbox?.clear();discovery?.clear();resetEventForm();events?.clear();user=null;profile=null;$('auth-view').hidden=false;$('profile-view').hidden=true;$('full-name').value='';$('username').value='';$('account-email').textContent='';$('user-id').textContent='';}
function selectMode(next){mode=next;const signup=mode==='signup';$('login-tab').classList.toggle('active',!signup);$('signup-tab').classList.toggle('active',signup);$('login-tab').setAttribute('aria-pressed',String(!signup));$('signup-tab').setAttribute('aria-pressed',String(signup));$('auth-heading').textContent=signup?'Zacznijmy od Ciebie':'Miło Cię widzieć';$('auth-description').textContent=signup?'Załóż konto i stwórz swój prywatny profil.':'Zaloguj się i wróć do swojego miejsca.';$('auth-submit').replaceChildren(document.createTextNode(signup?'Utwórz konto':'Zaloguj się'));$('repeat-wrap').hidden=!signup;$('repeat-password').required=signup;$('password').minLength=signup?8:1;$('password').autocomplete=signup?'new-password':'current-password';$('password').value='';$('repeat-password').value='';$('notice').hidden=true;}
function paintProfile(){const name=profile?.full_name||user?.email?.split('@')[0]||'Cześć';$('welcome').textContent=`Cześć, ${name}!`;$('avatar').textContent=name.slice(0,1).toUpperCase();$('account-email').textContent=user.email||'';$('full-name').value=profile?.full_name||'';$('username').value=profile?.unsername||'';$('user-id').textContent=user.id;$('save-status').textContent=profile?'Profil zapisany w Supabase.':'Uzupełnij dane i zapisz swój pierwszy profil.';}
async function enter(){const g=++generation;const verified=await api.currentUser();const loaded=await api.loadProfile(verified.id);if(g!==generation)return;user=verified;profile=loaded;$('auth-view').hidden=true;$('profile-view').hidden=false;$('notice').hidden=true;paintProfile();await safety.ensureConsent();await Promise.all([loadEvents(),inbox.load(),discovery.load(),admin.init()]);}
$('login-tab').onclick=()=>selectMode('login');$('signup-tab').onclick=()=>selectMode('signup');
$('show-password').onclick=()=>{const show=$('password').type==='password';$('password').type=show?'text':'password';$('show-password').textContent=show?'Ukryj':'Pokaż';$('show-password').setAttribute('aria-label',show?'Ukryj hasło':'Pokaż hasło');};
$('auth-form').onsubmit=e=>{e.preventDefault();busy($('auth-view'),async()=>{if(!api)throw new Error('Aplikacja nie jest jeszcze gotowa. Odśwież stronę.');const email=$('email').value.trim(),password=$('password').value;if(mode==='signup'){if(password!==$('repeat-password').value)throw new Error('Hasła muszą być takie same.');const data=await api.signUp(email,password);$('password').value='';$('repeat-password').value='';if(data?.access_token){await api.signIn(email,password);await enter();}else{selectMode('login');notify('Sprawdź skrzynkę e-mail i potwierdź adres. Potem wróć tutaj i zaloguj się. Jeśli adres ma już konto, możesz użyć dotychczasowego hasła.');}}else{await api.signIn(email,password);$('password').value='';await enter();}});};
$('resend').onclick=()=>busy($('auth-view'),async()=>{const email=$('email').value.trim();if(!$('email').checkValidity()||!email)throw new Error('Wpisz najpierw poprawny adres e-mail.');await api.resend(email);notify('Jeśli adres wymaga potwierdzenia, Supabase wyśle wiadomość. Sprawdź również spam.');});
$('profile-form').onsubmit=e=>{e.preventDefault();busy($('profile-view'),async()=>{const id=user?.id;if(!id)throw new Error('Zaloguj się ponownie.');const saved=await api.saveProfile(user,{full_name:$('full-name').value,username:$('username').value},Boolean(profile));if(user?.id!==id)return;profile=saved;paintProfile();notify('Twój profil został zapisany.');});};
$('reload-profile').onclick=()=>busy($('profile-view'),async()=>{await enter();notify('Profil odświeżony z bazy.');});
$('signout').onclick=()=>busy($('profile-view'),async()=>{generation++;let error;try{await api.signOut();}catch(e){error=e;}showAuth();notify(error?'Wylogowano z tej karty. Nie udało się potwierdzić unieważnienia sesji na serwerze.':'Wylogowano z tej karty.',Boolean(error));});
$('copy-id').onclick=()=>busy($('profile-view'),async()=>{await navigator.clipboard.writeText(user.id);notify('Identyfikator skopiowany.');});
async function boot(){try{api=createTogetherClient({url:SUPABASE_URL,key:SUPABASE_KEY});inbox=createNotificationInbox(api,{root:$('profile-view'),getUser:()=>user});events=createEventsController(api,{render:renderEvents,report:eventError});discovery=createDiscovery(api,{root:$('profile-view'),notice:notify,getUser:()=>user});safety=createSafety(api,{root:document.body,notice:notify});admin=createAdminPanel(api,{root:$('profile-view'),notice:notify,selectPanel});discovery.tab.onclick=()=>selectPanel('people');await api.health();$('connection').textContent='Połączono z Supabase';if(api.consumeRecoveryUrl()){safety.showRecovery();return;}if(await api.getSession())await enter();}catch(e){$('connection').textContent='Sprawdź połączenie';$('connection').classList.add('offline');notify(message(e),true);}}
enableInstall(document,notify);

function eventError(e){$('events-state').textContent='Nie udało się pobrać spotkań.';notify(e.code==='PGRST202'||e.code==='42P01'?'Moduł spotkań oczekuje na konfigurację bazy. Spróbuj ponownie później.':message(e),true);}
async function loadEvents(){if(!user||!events)return;$('events-state').textContent='Szukam spotkań…';await events.load({query:$('search-query').value,city:$('search-city').value,category:$('search-category').value,mine:$('search-mine').checked});}
function renderEvents(rows){
  $('events-list').replaceChildren();$('events-state').textContent=rows.length?rows.length+' spotkań przed Tobą':'Brak spotkań dla tych filtrów. Możesz zorganizować pierwsze.';
  for(const row of rows){const card=document.createElement('article');card.className='event-card';
    const add=(tag,text,cls)=>{const el=document.createElement(tag);el.textContent=text;if(cls)el.className=cls;card.append(el);};
    add('span',row.category,'event-category');add('h3',row.title);add('p',new Intl.DateTimeFormat('pl-PL',{dateStyle:'medium',timeStyle:'short'}).format(new Date(row.starts_at))+' · '+row.city);add('p',row.location);add('p',row.description,'event-description');add('p',row.attendee_count+' / '+row.capacity+' osób · '+(row.cancelled_at?'ODWOŁANE':row.is_host?'Organizujesz':row.joined?'Dołączono':'Zapisy otwarte'),'event-meta');
    if(row.is_host&&!row.cancelled_at){
      const edit=document.createElement('button');edit.type='button';edit.className='secondary';edit.textContent='Edytuj spotkanie';edit.onclick=()=>editEvent(row);card.append(edit);
      const cancel=document.createElement('button');cancel.type='button';cancel.className='secondary';cancel.textContent='Odwołaj spotkanie';cancel.onclick=()=>{if(!confirm('Odwołać spotkanie „'+row.title+'”? Zapisy zostaną zamknięte, a uczestnicy zobaczą status Odwołane.'))return;busy(card,async()=>{await events.cancel(row.id);if(editingEvent===row.id)resetEventForm();notify('Spotkanie odwołane. Historia zapisów została zachowana.');await loadEvents();});};card.append(cancel);
    }
    if(row.is_host){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent='Lista uczestników';const panel=document.createElement('div');panel.hidden=true;panel.setAttribute('aria-live','polite');b.setAttribute('aria-expanded','false');b.onclick=()=>{if(!panel.hidden){panel.hidden=true;b.setAttribute('aria-expanded','false');return;}busy(card,async()=>{const rows=await events.attendees(row.id);panel.replaceChildren();const note=document.createElement('p');note.className='fine';note.textContent='Nazwy podane przy zapisie, poza organizatorem. Nie są weryfikowaną tożsamością. Lista widoczna tylko dla Ciebie.';panel.append(note);if(!rows.length){const p=document.createElement('p');p.textContent='Nikt jeszcze nie dołączył.';panel.append(p);}else{const list=document.createElement('ol');for(const item of rows){const li=document.createElement('li');li.textContent=item.display_name+' · zapis: '+new Intl.DateTimeFormat('pl-PL',{dateStyle:'short',timeStyle:'short'}).format(new Date(item.joined_at));list.append(li);}panel.append(list);}panel.hidden=false;b.setAttribute('aria-expanded','true');});};card.append(b,panel);}
    if(!row.is_host&&!row.cancelled_at){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=row.joined?'Zrezygnuj':row.attendee_count>=row.capacity?'Brak miejsc':'Dołącz do spotkania';b.disabled=!row.joined&&row.attendee_count>=row.capacity;b.onclick=()=>{if(row.joined)busy(card,async()=>{await events.leave(row.id);notify('Zrezygnowano ze spotkania.');await loadEvents();});else showJoinForm(row,card);};card.append(b);} $('events-list').append(card);
  }
}
function showJoinForm(row,card){if(card.querySelector('form'))return;const form=document.createElement('form');const label=document.createElement('label');label.textContent='Nazwa widoczna tylko dla organizatora';const input=document.createElement('input');input.required=true;input.minLength=2;input.maxLength=60;input.name='display_name';input.autocomplete='off';input.placeholder='Np. Ania lub wybrany pseudonim';label.append(input);const note=document.createElement('p');note.className='fine';note.textContent='Podając nazwę i potwierdzając zapis, udostępnisz ją organizatorowi tego spotkania. Nie pobieramy danych z Twojego prywatnego profilu.';const submit=document.createElement('button');submit.type='submit';submit.className='primary';submit.textContent='Potwierdź dołączenie';const cancel=document.createElement('button');cancel.type='button';cancel.className='text-button';cancel.textContent='Anuluj zapis';cancel.onclick=()=>form.remove();form.append(label,note,submit,cancel);form.onsubmit=e=>{e.preventDefault();busy(card,async()=>{await events.joinNamed(row.id,input.value);notify('Dołączono do spotkania. Wybrana nazwa jest widoczna dla organizatora.');await loadEvents();});};card.append(form);input.focus();}
$('search-form').onsubmit=e=>{e.preventDefault();busy($('search-form'),loadEvents);};
function resetEventForm(){editingEvent=null;$('event-form').reset();$('event-form').querySelector('[type="submit"]').textContent='Utwórz spotkanie ↗';$('stop-editing')?.remove();$('create-details').open=false;}
function editEvent(row){editingEvent=row.id;const form=$('event-form');for(const name of ['title','description','city','location','category','capacity'])form.elements.namedItem(name).value=row[name];const d=new Date(row.starts_at);form.elements.namedItem('starts_at').value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);form.querySelector('[type="submit"]').textContent='Zapisz zmiany ↗';if(!$('stop-editing')){const b=document.createElement('button');b.id='stop-editing';b.type='button';b.className='secondary';b.textContent='Anuluj edycję';b.onclick=resetEventForm;form.append(b);}$('create-details').open=true;form.scrollIntoView({behavior:'smooth',block:'center'});form.elements.namedItem('title').focus();}
$('event-form').onsubmit=e=>{e.preventDefault();busy($('event-form'),async()=>{const id=editingEvent,values=Object.fromEntries(new FormData(e.target));if(id)await events.update(id,values);else await events.create(values);resetEventForm();notify(id?'Zmiany spotkania zapisane.':'Spotkanie utworzone. Jesteś organizatorem.');await loadEvents();});};
$('events-signout').onclick=()=>$('signout').click();
function selectPanel(name){for(const key of ['events','people','admin','account']){const panel=$(key+'-panel'),tab=$(key+'-tab');if(!panel||!tab)continue;const active=key===name;panel.hidden=!active;tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active));}}
$('events-tab').onclick=()=>selectPanel('events');$('account-tab').onclick=()=>selectPanel('account');
boot();


setInterval(()=>{if(user && document.visibilityState==='visible')inbox?.load();},30000);
document.addEventListener('visibilitychange',()=>{if(user && document.visibilityState==='visible')inbox?.load();});
